import json, sys

# The files may have multiple JSON objects concatenated; parse them properly
def parse_multi_json(path):
    with open(path) as f:
        content = f.read()
    # Try standard parse first
    try:
        return json.loads(content)
    except:
        pass
    # Try parsing as NDJSON or concatenated
    results = []
    decoder = json.JSONDecoder()
    idx = 0
    while idx < len(content):
        content_strip = content[idx:].lstrip()
        if not content_strip:
            break
        idx = len(content) - len(content_strip)
        obj, end = decoder.raw_decode(content, idx)
        results.append(obj)
        idx += end
    return results

baseline = parse_multi_json('baseline-packages.json')
after = parse_multi_json('after-cpm-packages.json')

def extract_packages(data):
    pkgs = {}
    if isinstance(data, list):
        for d in data:
            pkgs.update(extract_packages(d))
        return pkgs
    for proj in data.get('projects', []):
        proj_name = proj.get('path', '').split('/')[-1]
        frameworks = proj.get('frameworks', [])
        for fw in frameworks:
            for pkg in fw.get('topLevelPackages', []):
                key = (proj_name, pkg['id'])
                pkgs[key] = pkg.get('resolvedVersion', pkg.get('requestedVersion'))
    return pkgs

